example.snippet:
package main

import (
	"context"
	"time"
)

type MyModule struct{}

// Build and publish image with OCI labels
func (m *MyModule) Build(
	ctx context.Context,
) (string, error) {
	ref, err := dag.Container().
		From("alpine").
		WithLabel("org.opencontainers.image.title", "my-alpine").
		WithLabel("org.opencontainers.image.version", "1.0").
		WithLabel("org.opencontainers.image.created", time.Now().String()).
		WithLabel("org.opencontainers.image.source", "https://github.com/alpinelinux/docker-alpine").
		WithLabel("org.opencontainers.image.licenses", "MIT").
		Publish(ctx, "ttl.sh/my-alpine")

	if err != nil {
		return "", err
	}

	return ref, nil
}

from datetime import datetime, timezone
from dagger import dag, function, object_type
@object_type class MyModule: @function async def build(self) -> str: """Build and publish image with OCI labels""" ref = ( dag.container() .from_("alpine") .with_label("org.opencontainers.image.title", "my-alpine") .with_label("org.opencontainers.image.version", "1.0") .with_label( "org.opencontainers.image.created", datetime.now(timezone.utc).isoformat(), ) .with_label( "org.opencontainers.image.source", "https://github.com/alpinelinux/docker-alpine", ) .with_label("org.opencontainers.image.licenses", "MIT") .publish("ttl.sh/my-alpine") ) return await ref

import { dag, object, func } from "@dagger.io/dagger"

@object()
class MyModule {
  /**
   * Build and publish image with OCI labels
   */
  @func()
  async build(): Promise {
    const ref = await dag
      .container()
      .from("alpine")
      .withLabel("org.opencontainers.image.title", "my-alpine")
      .withLabel("org.opencontainers.image.version", "1.0")
      .withLabel("org.opencontainers.image.created", new Date())
      .withLabel(
        "org.opencontainers.image.source",
        "https://github.com/alpinelinux/docker-alpine",
      )
      .withLabel("org.opencontainers.image.licenses", "MIT")
      .publish("ttl.sh/hello-dagger")

    return ref
  }
}
